// ring.go

package logfan

import (
    "fmt"
    "log/slog"
    "sync"
)

// Ring is an in-memory ring-buffer slog handler.
type Ring struct {
    mu       sync.RWMutex
    capacity int
    records  []slog.Record
    start    int
    count    int
}

// NewRing creates a ring-buffer slog handler with the given capacity.
func NewRing(capacity int) (*Ring, error) {
    if capacity <= 0 {
        return nil, fmt.Errorf("logfan: ring capacity must be positive, got %d", capacity)
    }
    return &Ring{
        capacity: capacity,
        records:  make([]slog.Record, capacity),
    }, nil
}

// Enabled returns true for all levels.
func (r *Ring) Enabled(_ context.Context, _ slog.Level) bool {
    return true
}

// Handle stores a record in the ring buffer.
func (r *Ring) Handle(_ context.Context, record slog.Record) error {
    r.mu.Lock()
    defer r.mu.Unlock()

    // make a copy of the record to store
    rec := slog.NewRecord(record.Time, record.Level, record.Message, record.PC)
    record.Attrs(func(a slog.Attr) bool {
        rec.AddAttrs(a)
        return true
    })

    idx := (r.start + r.count) % r.capacity
    if r.count == r.capacity {
        // overwrite oldest
        r.records[r.start] = rec
        r.start = (r.start + 1) % r.capacity
    } else {
        r.records[idx] = rec
        r.count++
    }
    return nil
}

// WithAttrs returns a handler that adds the given attrs.
func (r *Ring) WithAttrs(attrs []slog.Attr) slog.Handler {
    return &handler{r, attrs, nil}
}

// WithGroup returns a handler that opens a group.
func (r *Ring) WithGroup(name string) slog.Handler {
    return &handler{r, nil, []string{name}}
}

// Records returns a copy of the buffered records, oldest first.
func (r *Ring) Records() []slog.Record {
    r.mu.RLock()
    defer r.mu.RUnlock()

    result := make([]slog.Record, r.count)
    for i := 0; i < r.count; i++ {
        idx := (r.start + i) % r.capacity
        result[i] = copyRecord(r.records[idx])
    }
    return result
}

